CREATE TABLE public_profiles (organization_id VARCHAR(36) PRIMARY KEY, slug VARCHAR(60) NOT NULL UNIQUE, tagline VARCHAR(140) NOT NULL, presentation TEXT NOT NULL, cover_url TEXT NOT NULL, logo_url TEXT NOT NULL, phone VARCHAR(30) NOT NULL, whatsapp VARCHAR(30) NOT NULL, email VARCHAR(254) NOT NULL, website TEXT NOT NULL, hours VARCHAR(140) NOT NULL, office_region VARCHAR(2) NOT NULL, office_commune VARCHAR(100) NOT NULL, coverage_json TEXT NOT NULL, updated_at VARCHAR(32) NOT NULL, FOREIGN KEY(organization_id) REFERENCES organizations(id));
